import { servicesData } from "./services-data";

export interface ServiceExampleItem {
  title: string;
  description: string;
}

export interface ServiceFAQ {
  question: string;
  answer: string;
}

export interface ServiceComparisonTable {
  headers: string[];
  rows: string[][];
}

export interface ServiceDetail {
  title: string; // Matches the title in constants.ts
  sentenceTitle?: string; // Lowercase version for sentences (preserves acronyms like AI, SaaS)
  coreValue: string;
  examples: ServiceExampleItem[];
  benefits?: { title: string; description: string }[];
  process?: { step: string; title: string; description: string }[];
  seoKeywords?: string[];
  faqs?: ServiceFAQ[];
  comparisonTable?: ServiceComparisonTable; // Added for GEO
  codeSnippet?: { language: string; code: string; label: string }; // Added for GEO (Code-First Authority)
}

export const serviceExamples: Record<string, ServiceDetail> = servicesData.reduce((acc, s) => {
  acc[s.title] = s.details;
  return acc;
}, {} as Record<string, ServiceDetail>);
